import{_ as a,o,c as t,a0 as c}from"./chunks/framework.CNDWyMYS.js";const h=JSON.parse('{"title":"luarocks unpack","description":"","frontmatter":{},"headers":[],"relativePath":"luarocks_unpack.md","filePath":"luarocks_unpack.md"}'),r={name:"luarocks_unpack.md"};function s(n,e,i,d,l,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="luarocks-unpack" tabindex="-1">luarocks unpack <a class="header-anchor" href="#luarocks-unpack" aria-label="Permalink to &quot;luarocks unpack&quot;">​</a></h1><p>Unpack the contents of a rock.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p><code>luarocks unpack [--force] {&lt;rock&gt; | &lt;rockspec&gt; | &lt;name&gt; [&lt;version&gt;]}</code></p><p>Unpacks the contents of a rock in a newly created directory under the current directory. Argument may be a rock file, a rockspec file, or the name of a rock/rockspec in a remote repository.</p><p>If <code>--force</code> is passed, files are unpacked even if the output directory already exists.</p><p>When a rock is given, LuaRocks creates a directory and extracts the contents of a rock inside it. If it is a <code>.src.rock</code> file, it also extracts the sources, and copies the rock&#39;s rockspec to the root of the sources directory, so that you can run <a href="./luarocks_make.html">luarocks make</a>.</p><p>When a rockspec is given, LuaRocks creates a directory and then fetches and extracts the sources for the module inside it. It also copies the rockspec to the root of the sources directory.</p><p>When a binary rock is given, it just extracts the contents of the rock in the created directory for further inspection. To fetch the sources, you can run <code>luarocks unpack</code> again on the rockspec file that will be extracted from the binary rock.</p><p>When a name (and optionally a version) is given, LuaRocks tries to download a source rock or a rockspec from remote repositories, and then proceeds as if the obtained file was provided locally.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks unpack luafilesystem 1.4.0</span></span></code></pre></div><p>This fetches <code>luafilesystem-1.4.0-1.src.rock</code> from the remote repository and creates in the current directory a directory called <code>luafilesystem-1.4.0-1</code> with the contents of the rock, including the LuaFileSystem sources unpacked. You will then be able to go into the <code>luafilesystem-1.4.0-1/luafilesystem-1.4.0</code> directory and run <a href="./luarocks_make.html">luarocks make</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks unpack copas-1.1.1-1.rockspec</span></span></code></pre></div><p>Assuming you have <code>copas-1.1.1-1.rockspec</code> in the current directory, this creates in the current directory a directory called <code>copas-1.1.1-1</code> with the rockspec and the Copas sources unpacked. You will then be able to go into the <code>copas-1.1.1-1/copas-1.1.1</code> directory and run <a href="./luarocks_make.html">luarocks make</a>.</p><p>While the extracted directory names may look repetitive, note that the first directory is a directory in a LuaRocks &quot;name-version-revision&quot; format, and the second directory is the directory contained inside the sources archives, which may be in any format, and in some cases may not even exist.</p>',16)])])}const k=a(r,[["render",s]]);export{h as __pageData,k as default};
